import {safeMetric} from './data.js';
const HIVES=['NATIVA-01','NATIVA-02'];
const root=document.getElementById('app');let db=null,selected='NATIVA-02',tab='overview',users=[],busy=false,refreshTimer=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(n,d=1)=>typeof n==='number'&&Number.isFinite(n)?n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const time=x=>x?new Date(x).toLocaleString('pt-BR'):'—';
const last=h=>h?.records?.filter(r=>r.simulated===false).at(-1)||null;
const metric=(r,key)=>r?safeMetric(r.packet,key):null;
const age=r=>r?Date.now()-Date.parse(r.receivedAt):Infinity;
const online=(h,r)=>!!h?.enabled&&!!r&&age(r)<(h.settings?.offlineSeconds||120)*1000;
const showStatus=(h,r)=>!h?.enabled?['Desativada','off']:!r?['Aguardando','off']:online(h,r)?['Online','online']:['Sem comunicação',''];
async function api(endpoint,payload){const res=await fetch('/api/'+endpoint,{method:payload===undefined?'GET':'POST',headers:payload===undefined?{}:{'Content-Type':'application/json'},body:payload===undefined?undefined:JSON.stringify(payload),credentials:'same-origin'});let data;try{data=await res.json()}catch{throw Error('O servidor retornou uma resposta inválida.')}if(!res.ok)throw Object.assign(Error(data.error||'Erro '+res.status),{status:res.status});return data}
function flash(msg,error=false){const n=document.getElementById('notice');if(!n)return;n.textContent=msg;n.hidden=!msg;n.className='notice'+(error?' error':'')}
function login(){root.innerHTML=`<div class="login-shell"><div class="login-art"><div><div class="logo">NATIVA <span>BOX</span></div><div class="tagline">MONITORAMENTO DE COLMEIAS</div></div><div><p class="eyebrow">OBSERVATÓRIO 2.0</p><h1>Tecnologia para cuidar da vida.</h1><p>Monitore as duas colmeias, acompanhe as condições ambientais e consulte os registros reais de cada estação.</p></div><small>Projeto Honey Monitor · ESP32 e sensores ambientais</small></div><div class="login-box"><section class="panel"><p class="eyebrow">ÁREA SEGURA</p><h2>Acesse seu observatório</h2><p class="sub">Utilize sua conta já cadastrada na Nativa Box.</p><p id="notice" class="notice" hidden></p><form id="loginForm"><label class="field">E-mail<input type="email" name="email" autocomplete="username" required></label><label class="field">Senha<input type="password" name="password" autocomplete="current-password" required></label><button class="primary" type="submit">Entrar no dashboard</button></form></section></div></div>`;
document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('login',Object.fromEntries(new FormData(e.target)));await fetchState()}catch(x){flash(x.message,true)}finally{b.disabled=false}}}
function tile(label,value,note){return `<article class="tile"><div class="tile-label">${label}</div><div class="big">${value}</div><div class="tile-note">${note}</div></article>`}
function hiveCard(id){const h=db.hives[id],r=last(h),[label,cl]=showStatus(h,r);return `<article class="hive-card ${selected===id?'selected':''}" data-hive="${id}" tabindex="0" role="button" aria-label="Selecionar ${id}"><div class="hive-top"><span class="hive-id">ESTAÇÃO ${id.slice(-2)}</span><span class="status ${cl}"><span class="dot"></span>${label}</span></div><h3>${id}</h3><div class="muted">${r?'Última recepção: '+time(r.receivedAt):'Nenhuma transmissão registrada'}</div><div class="hive-stats"><div><small>Temperatura</small><strong>${val(metric(r,'ti'))}°</strong></div><div><small>Umidade</small><strong>${val(metric(r,'hi'))}%</strong></div><div><small>Bateria</small><strong>${val(metric(r,'bat_v'),2)} V</strong></div></div></article>`}
function metricTile(name,value,note=''){return `<div class="metric"><p>${name}</p><strong>${value}</strong>${note?`<div class="muted">${note}</div>`:''}</div>`}
function chart(rows,key){const pts=rows.map(r=>({t:Date.parse(r.receivedAt),v:metric(r,key),boot:r.bootId,seq:r.packet.seq})).filter(p=>Number.isFinite(p.t));const good=pts.filter(p=>p.v!==null);if(good.length<2)return '<p class="muted">Ainda não há duas medições válidas para formar um gráfico.</p>';const min=Math.min(...good.map(p=>p.v)),max=Math.max(...good.map(p=>p.v)),pad=Math.max((max-min)*.12,.25),lo=min-pad,hi=max+pad,t0=pts[0].t,t1=pts.at(-1).t;const X=t=>52+((t-t0)/Math.max(1,t1-t0))*655,Y=v=>190-(v-lo)/(hi-lo)*165;let seg=[],prev=null;for(const p of pts){if(p.v===null){prev=null;continue;}if(prev&&p.boot===prev.boot&&p.seq===prev.seq+1&&p.t-prev.t<=(db.hives[selected]?.settings?.offlineSeconds||120)*1000)seg.push(`<line x1="${X(prev.t)}" y1="${Y(prev.v)}" x2="${X(p.t)}" y2="${Y(p.v)}" stroke="#2c8764" stroke-width="2.5"/>`);seg.push(`<circle cx="${X(p.t)}" cy="${Y(p.v)}" r="2.6" fill="#c5a157"><title>${time(p.t)}: ${val(p.v,2)}</title></circle>`);prev=p;}return `<svg viewBox="0 0 740 235" role="img" aria-label="Gráfico do histórico da métrica selecionada"><line x1="50" y1="190" x2="708" y2="190" stroke="#cbdad0"/><line x1="50" y1="25" x2="50" y2="190" stroke="#cbdad0"/><text x="4" y="32" fill="#698173" font-size="12">${val(hi)}</text><text x="4" y="190" fill="#698173" font-size="12">${val(lo)}</text>${seg.join('')}<text x="52" y="221" fill="#698173" font-size="11">${esc(new Date(t0).toLocaleDateString('pt-BR'))}</text><text x="612" y="221" fill="#698173" font-size="11">${esc(new Date(t1).toLocaleDateString('pt-BR'))}</text></svg>`}
function layout(){const active=HIVES.filter(id=>db.hives[id]?.enabled).length;const connected=HIVES.filter(id=>online(db.hives[id],last(db.hives[id]))).length;const total=HIVES.reduce((n,id)=>n+(db.hives[id]?.records?.length||0),0);let content='';if(tab==='overview'){const h=db.hives[selected],r=last(h);content=`<p class="eyebrow">ACOMPANHAMENTO AMBIENTAL</p><h1>Seu apiário, em um só lugar.</h1><p class="sub">Medições reais, histórico e funcionamento das estações NATIVA-01 e NATIVA-02.</p><section class="summary">${tile('Estações online',connected+' / 2','Com transmissão dentro do prazo configurado')}${tile('Colmeias ativadas',active+' / 2','Controle individual no painel administrativo')}${tile('Registros disponíveis',String(total),'Retenção máxima: 1.000 por colmeia')}</section><div class="section-head"><h2>Minhas colmeias</h2><span class="pill">2 estações</span></div><section class="hives">${HIVES.map(hiveCard).join('')}</section><div class="section-head"><h2>Detalhes · ${selected}</h2><span class="pill">${showStatus(h,r)[0]}</span></div><div class="detail-grid"><section class="panel"><h3>Condições ambientais</h3><div class="metric-grid">${metricTile('Temperatura interna',val(metric(r,'ti'))+' °C','SHT31 interno')}${metricTile('Temperatura externa',val(metric(r,'te'))+' °C','SHT31 externo')}${metricTile('Umidade interna',val(metric(r,'hi'))+' %')}${metricTile('Umidade externa',val(metric(r,'he'))+' %')}${metricTile('Tensão da bateria',val(metric(r,'bat_v'),2)+' V','Leitura do ADC; validar calibração')}${metricTile('Peso da colmeia','—','Indisponível até calibrar o HX711')}</div></section><section class="panel"><h3>Atividade e diagnóstico</h3><div class="metric-grid">${metricTile('Contador IR 1',val(metric(r,'ir1'),0),'Verificar mapeamento físico')}${metricTile('Contador IR 2',val(metric(r,'ir2'),0),'Verificar mapeamento físico')}${metricTile('Feixe A',metric(r,'ir_a')===0?'Livre':metric(r,'ir_a')===1?'Bloqueado':'—')}${metricTile('Feixe B',metric(r,'ir_b')===0?'Livre':metric(r,'ir_b')===1?'Bloqueado':'—')}${metricTile('Som relativo',val(metric(r,'som_pp'),0)+' ADC','Não representa decibéis')}${metricTile('Última sequência',r?String(r.packet.seq):'—')}</div><p class="hint">IR ainda depende de validação da contagem com passagem real de abelhas. Números não são tratados como contagem comprovada de indivíduos.</p></section></div>`}
else if(tab==='history'){content=`<p class="eyebrow">EVOLUÇÃO DOS DADOS</p><h1>Histórico de medições.</h1><p class="sub">Dados recebidos na nuvem; sem amostras inventadas.</p><div class="section-head"><h2>${selected}</h2><div class="select-row"><select id="histHive">${HIVES.map(id=>`<option value="${id}" ${id===selected?'selected':''}>${id}</option>`).join('')}</select><button id="csv" class="outline">Exportar CSV</button></div></div><section class="panel"><div class="select-row"><label class="field">Métrica<select id="metricSelect"><option value="ti">Temperatura interna (°C)</option><option value="te">Temperatura externa (°C)</option><option value="hi">Umidade interna (%)</option><option value="he">Umidade externa (%)</option><option value="bat_v">Bateria (V)</option><option value="som_pp">Som relativo (ADC)</option><option value="ir1">IR 1</option><option value="ir2">IR 2</option></select></label><label class="field">Período<select id="periodSelect"><option value="24">Últimas 24 horas</option><option value="168">Últimos 7 dias</option><option value="0">Todo histórico disponível</option></select></label></div><div class="graph" id="plot"></div><p class="hint">Horário de recepção do servidor. Até 1.000 registros armazenados por colmeia no banco atual.</p></section>`}
else if(tab==='alerts'){const h=db.hives[selected],events=h?.events||[];content=`<p class="eyebrow">OCORRÊNCIAS</p><h1>Alertas e eventos.</h1><p class="sub">Histórico de mudanças de condição detectadas pelo servidor.</p><div class="section-head"><h2>${selected}</h2><div class="select-row"><select id="histHive">${HIVES.map(id=>`<option value="${id}" ${id===selected?'selected':''}>${id}</option>`).join('')}</select></div></div><section class="panel"><h3>Eventos recentes</h3><ul class="events">${events.length?events.slice(-30).reverse().map(e=>`<li>${esc(time(e.at))} · ${esc(e.message)}</li>`).join(''):'<li>Nenhum evento registrado.</li>'}</ul><p class="hint">Alertas exibidos no painel. O backend atual não envia notificações externas.</p></section>`}
else{const admin=db.user.role==='admin';const h=db.hives[selected];content=`<p class="eyebrow">CONFIGURAÇÕES</p><h1>Administração.</h1><p class="sub">Controle das duas estações e gerenciamento de acesso.</p>${admin?`<div class="section-head"><h2>Configurar colmeia</h2><select id="histHive">${HIVES.map(id=>`<option value="${id}" ${id===selected?'selected':''}>${id}</option>`).join('')}</select></div><section class="panel"><form id="settings"><div class="form-grid"><label class="field"><span>Colmeia ativada</span><input name="hiveEnabled" type="checkbox" ${h.enabled?'checked':''}></label><label class="field"><span>Alertas ativados</span><input name="enabled" type="checkbox" ${h.settings.enabled?'checked':''}></label>${[['batteryLow','Bateria baixa (V)'],['batteryHysteresis','Histerese da bateria (V)'],['tempLow','Temperatura mínima (°C)'],['tempHigh','Temperatura máxima (°C)'],['tempHysteresis','Histerese temperatura (°C)'],['offlineSeconds','Sem comunicação (segundos)'],['repeatSeconds','Repetição de alerta (segundos)']].map(([key,label])=>`<label class="field">${label}<input name="${key}" type="number" step="any" value="${Number(h.settings[key])}" required></label>`).join('')}</div><button class="primary">Salvar configurações</button></form></section><div class="section-head"><h2>Contas do sistema</h2></div><section class="panel"><ul class="events" id="userList"><li>Carregando...</li></ul><h3>Criar ou atualizar outra conta</h3><form id="userForm"><div class="form-grid"><label class="field">E-mail<input type="email" name="email" required></label><label class="field">Senha nova (mín. 14 caracteres)<input type="password" name="password" minlength="14" maxlength="200" required autocomplete="new-password"></label><label class="field">Perfil<select name="role"><option value="viewer">Consulta</option><option value="admin">Administrador</option></select></label><label class="field">Ativo<input type="checkbox" name="enabled" checked></label></div><button class="primary">Salvar usuário</button></form><p class="hint">Esta operação não permite mudar a própria conta. Senhas não aparecem na interface.</p></section>`:'<section class="panel">Sua conta possui permissão de consulta.</section>'}`}
root.innerHTML=`<div class="shell"><aside class="sidebar"><div><div class="logo">NATIVA <span>BOX</span></div><div class="tagline">OBSERVATÓRIO 2.0</div></div><nav class="nav"><button data-tab="overview" class="${tab==='overview'?'active':''}">Visão geral</button><button data-tab="history" class="${tab==='history'?'active':''}">Histórico</button><button data-tab="alerts" class="${tab==='alerts'?'active':''}">Alertas</button><button data-tab="admin" class="${tab==='admin'?'active':''}">Administração</button></nav><div class="sidebar-bottom">Duas colmeias oficiais<br>Projeto Honey Monitor<br>Transmissão ESP32 → Vercel → Neon</div></aside><main class="main"><header class="topbar"><div><p class="eyebrow">PLATAFORMA DE MONITORAMENTO</p><p>Leituras atualizadas automaticamente a cada 10 segundos</p></div><div class="top-right"><span class="pill">${esc(db.user.role==='admin'?'Administrador':'Consulta')}</span><button id="logout" class="outline">Sair</button></div></header><p class="notice" id="notice" hidden></p>${content}<footer class="footer">Nativa Box 2.0 · Dados reais apenas · Indicadores ausentes permanecem indisponíveis.</footer></main></div>`;
root.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;layout()});root.querySelectorAll('[data-hive]').forEach(x=>{const select=()=>{selected=x.dataset.hive;layout()};x.onclick=select;x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});document.getElementById('logout').onclick=async()=>{try{await api('logout',{});db=null;login()}catch(x){flash(x.message,true)}};
const hs=document.getElementById('histHive');if(hs)hs.onchange=()=>{selected=hs.value;layout()};
const sm=document.getElementById('settings');if(sm)sm.onsubmit=async e=>{e.preventDefault();const f=e.target,s={...db.hives[selected].settings};for(const k of ['batteryLow','batteryHysteresis','tempLow','tempHigh','tempHysteresis','offlineSeconds','repeatSeconds'])s[k]=Number(f.elements[k].value);s.enabled=f.elements.enabled.checked;s.weightEnabled=false;try{await api('settings',{hive:selected,settings:s,enabled:f.elements.hiveEnabled.checked});await fetchState();flash('Configuração salva com sucesso.')}catch(x){flash(x.message,true)}};
const uf=document.getElementById('userForm');if(uf){uf.onsubmit=async e=>{e.preventDefault();const f=e.target;try{await api('users',{...Object.fromEntries(new FormData(f)),enabled:f.elements.enabled.checked});f.reset();await getUsers();flash('Usuário salvo.')}catch(x){flash(x.message,true)}};getUsers()}
const csv=document.getElementById('csv');if(csv)csv.onclick=()=>location.href='/api/export?hive='+encodeURIComponent(selected);
if(tab==='history'){const sel=document.getElementById('metricSelect'),period=document.getElementById('periodSelect'),plot=document.getElementById('plot');const update=()=>{const hrs=Number(period.value),rows=(db.hives[selected]?.records||[]).filter(x=>x.simulated===false&&(!hrs||Date.parse(x.receivedAt)>Date.now()-hrs*3600000)).slice(-300);plot.innerHTML=chart(rows,sel.value)};sel.onchange=update;period.onchange=update;update()}}
async function getUsers(){const ul=document.getElementById('userList');if(!ul)return;try{const r=await api('users');ul.replaceChildren();for(const u of r.users){const li=document.createElement('li');li.textContent=u.email+' · '+(u.role==='admin'?'Administrador':'Consulta')+' · '+(u.enabled?'Ativo':'Desativado');ul.append(li)}}catch(x){ul.textContent=x.message}}
async function fetchState(){if(busy)return;busy=true;try{const incoming=await api('state');db=incoming;if(!db.hives?.[selected])selected='NATIVA-01';if(tab==='admin'&&db.user.role!=='admin')tab='overview';layout()}catch(x){if(x.status===401){db=null;login()}else if(db){flash('Falha ao atualizar: '+x.message,true)}else{login();flash(x.message,true)}}finally{busy=false}}
login();fetchState();refreshTimer=setInterval(()=>{if(db&&tab!=='admin')fetchState()},10000);
